#!/usr/bin/env bash
# Marleybop theme for Proxmox VE 1.0.0 - self-contained installer (generated by build.sh, do not edit).
#
#   install:    bash install.sh            (or: curl -fsSL <url>/install.sh | bash)
#   uninstall:  bash install.sh uninstall  (or: marleybop-pve-theme uninstall)
#
# What it does on the node, all undone by "uninstall":
#   - unpacks the theme files to /usr/local/share/marleybop-pve-theme
#   - writes theme-marleybop.css, 5 font files and marleybop-theme.js into
#     /usr/share/javascript/proxmox-widget-toolkit/themes/
#   - adds one line to proxmoxlib.js (Color Theme list) and to index.html.tpl (script tag)
#   - adds an apt hook that repeats those two edits after a Proxmox update
#   - reloads pveproxy
# Nothing is downloaded: everything is inside this file.
set -euo pipefail

main() {
    local share=/usr/local/share/marleybop-pve-theme
    local bin=/usr/local/sbin/marleybop-pve-theme
    local want=e9e2992953223b46c4a2a6383a1b18e9fd54d620cc7f44679595394c368eaaec
    local cmd=${1:-install}

    [ "$(id -u)" = 0 ] || { echo "error: run this as root (on the Proxmox node itself)" >&2; exit 1; }

    case "$cmd" in
        uninstall|status)
            if [ -x "$bin" ]; then exec "$bin" "$@"; fi
            echo "The Marleybop theme is not installed on this node."; exit 0 ;;
        install) ;;
        *) echo "usage: install.sh [install [--no-default] | uninstall | status]" >&2; exit 1 ;;
    esac

    for tool in base64 tar gzip sha256sum sed; do
        command -v "$tool" >/dev/null 2>&1 || { echo "error: $tool is needed but not installed" >&2; exit 1; }
    done

    local tmp got
    tmp=$(mktemp -d)
    # expanded now on purpose: tmp is local to main and gone when the trap runs
    # shellcheck disable=SC2064
    trap "rm -rf '$tmp'" EXIT
    payload | base64 -d > "$tmp/payload.tgz"
    got=$(sha256sum "$tmp/payload.tgz" | cut -d' ' -f1)
    [ "$got" = "$want" ] || { echo "error: the installer is damaged or incomplete (checksum mismatch). Download it again." >&2; exit 1; }

    mkdir -p "$tmp/x"
    tar -xzf "$tmp/payload.tgz" -C "$tmp/x" --no-same-owner
    rm -rf "$share"
    mkdir -p "$share" "$(dirname "$bin")"
    cp -R "$tmp/x/." "$share/"
    chmod -R u=rwX,go=rX "$share"
    chmod 0755 "$share/apply.sh"
    ln -sfn "$share/apply.sh" "$bin"

    shift || true
    "$bin" install "$@"
}

